gTs(){return'\u0646\u0627\u06a4\u06ce \u062e\u0627\u0646\u06ce (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 "\u06a9\u06d5\u06a4\u0627\u0646")'},
gTt(){return"\u0647\u06d5\u0644\u0628\u0698\u0627\u0631\u062a\u0646\u060c \u0628 \u06a9\u06c6\u0645\u0627\u06cc\u06ce \u0698\u06ce\u06a9 \u062c\u0648\u062f\u0627 (\u06a4\u0627\u0644\u0627 \u0628\u0647\u06ce\u0644\u06d5 \u0628\u06c6 \u0646\u06a4\u06cc\u0633\u06cc\u0646\u0627 \u0626\u0627\u0632\u0627\u062f)"},
gTu(){return"\u062f\u06d5\u0645 \u0647\u0627\u062a\u06cc"},
gTv(){return"\u0628\u06c6 \u06a9\u06ce"},
guo(){return"\u0647\u06d5\u0645\u06cc \u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06cc (\u062c\u0627\u0631\u06d5\u06a9\u06ce \u062f\u0647\u06ce\u062a\u06d5 \u062f\u0627\u0646\u0627\u0646)"},
gF7(){return"\u0628\u06c6 \u0647\u06d5\u0631 \u0633\u06d5\u0631\u06d5\u062f\u0627\u0646\u06d5\u06a9\u06ce (\u062f \u0647\u06d5\u0631 \u0633\u06d5\u0631\u06d5\u062f\u0627\u0646\u06d5\u06a9\u06ce \u062f\u0627 \u062f\u0647\u06ce\u062a\u06d5 \u06af\u0648\u0647\u06c6\u0695\u06cc\u0646)"},
gLW(){return"\u0631\u06ce\u06a9\u062e\u0633\u062a\u0646"},
gKz(){return"\u0631\u06ce\u06a9\u062e\u0633\u062a\u0646\u06ce\u0646 \u0644\u0642\u06cc"},
gKA(){return"\u0646\u0627\u06a4\u06ce \u0644\u0642\u06cc"},
CI(a){return"\u0646\u0631\u062e\u06ce \u06af\u0648\u0647\u06c6\u0695\u06cc\u0646\u06ce \u2014 1 \u062f\u06c6\u0644\u0627\u0631 \u062f\u06a9\u06d5\u062a\u06d5 \u0686\u06d5\u0646\u062f "+a},
