gL7(){return"\u062f\u06d5\u0645\u06ce \u06a4\u06d5\u06a9\u0631\u0646\u06ce"},
gKG(){return"\u062f\u06d5\u0645\u06ce \u06af\u0631\u062a\u0646\u06ce"},
