gL2(){return"\u0647\u06d5\u0698\u0645\u0627\u0631\u0627 \u0645\u0646"},
gCF(){return"\u067e\u06d5\u06cc\u06a4\u0627 \u0646\u0647\u06ce\u0646\u06cc \u06cc\u0627 \u0646\u0648\u06a9\u06d5"},
gL3(){return"\u0626\u06cc\u0645\u06d5\u06cc\u0644\u0627 \u0646\u0648\u06cc"},
gL5(){return"\u067e\u06d5\u06cc\u06a4\u0627 \u0646\u0647\u06ce\u0646\u06cc \u06cc\u0627 \u0646\u0648\u06cc"},
gKE(){return"\u06af\u0648\u0647\u06c6\u0695\u06cc\u0646\u0627 \u0626\u06cc\u0645\u06d5\u06cc\u0644\u06ce"},
gKF(){return"\u06af\u0648\u0647\u06c6\u0695\u06cc\u0646\u0627 \u067e\u06d5\u06cc\u06a4\u0627 \u0646\u0647\u06ce\u0646\u06cc"},
gKR(){return"\u06af\u0648\u0647\u06c6\u0695\u06cc\u0646\u0627 \u0626\u06cc\u0645\u06d5\u06cc\u0644\u0627 \u062a\u06d5 \u0628\u06d5\u0644\u06a9\u06cc \u067e\u06ce\u062f\u06a4\u06cc \u0628 \u067e\u0634\u062a\u0631\u0627\u0633\u062a\u06a9\u0631\u0646\u0627 \u0644\u06cc\u0646\u06a9\u06d5\u06a9\u06ce \u0628\u06cc\u062a \u06cc\u06ce \u0628\u06c6 \u0646\u0627\u06a4 \u0648 \u0646\u06cc\u0634\u0627\u0646\u06ce \u0646\u0648\u06cc \u062f\u0647\u06ce\u062a\u06d5 \u0647\u0646\u0627\u0631\u062a\u0646 \u0628\u06d5\u0631\u06cc \u06a9\u0627\u0631 \u0628\u06a9\u06d5\u062a."},
gCH(){return"\u0698\u06ce\u0628\u0631\u0646\u0627 \u0647\u06d5\u0698\u0645\u0627\u0631\u0627 \u0645\u0646"},
gKI(){return"\u062f\u0627\u062e\u0648\u0627\u0632\u0627 \u0698\u06ce\u0628\u0631\u0646\u0627 \u0647\u06d5\u0698\u0645\u0627\u0631\u0627 \u062e\u06c6 \u0628\u06a9\u06d5. \u062f\u06d5\u0633\u062a\u0628\u06d5\u062c\u06ce \u062a\u0648 \u062f\u06d5\u0631\u062f\u06a9\u06d5\u06a4\u06cc \u0648 \u0686\u06cc\u062a\u0631 \u0646\u06d5\u0634\u06ce\u06cc \u0628\u0686\u06cc\u06d5 \u0698\u0648\u0648\u0631\u060c \u0648 \u0632\u0627\u0646\u06cc\u0627\u0631\u06cc\u06cc\u06ce\u0646 \u062a\u06d5 \u06cc\u06ce\u0646 \u062a\u0627\u06cc\u0628\u06d5\u062a \u062f \u0646\u0627\u06a4\u0628\u06d5\u0631\u0627 30 \u0631\u06c6\u0698\u0627\u0646\u062f\u0627 \u062f\u0647\u06ce\u0646\u06d5 \u0698\u06ce\u0628\u0631\u0646. \u062a\u06c6\u0645\u0627\u0631\u06ce\u0646 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06ce (\u0646\u06d5\u062e\u06c6\u0634\u060c \u0633\u06d5\u0631\u062f\u0627\u0646\u060c \u062f\u0627\u0646\u060c \u0645\u0648\u0648\u0686\u06d5) \u062f \u062f\u06d5\u0641\u062a\u06d5\u0631\u06ce \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06ce \u062f\u0627 \u062f\u0645\u06cc\u0646\u0646. \u0626\u06d5\u06af\u06d5\u0631 \u062a\u0648 \u062a\u0646\u06ce \u0628\u06d5\u0695\u06ce\u06a4\u06d5\u0628\u06d5\u0631\u06ce \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06ce\u060c \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u06ce \u0628 \u0645\u06d5 \u0628\u06a9\u06d5 \u062f\u0627 \u0647\u06d5\u0645\u06cc \u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u0628\u0647\u06ce\u062a\u06d5 \u06af\u0631\u062a\u0646."},
gCG(){return"\u0698\u06ce\u0628\u0631\u0646\u0627 \u0647\u06d5\u0698\u0645\u0627\u0631\u0627 \u0645\u0646"},
gKJ(){return"\u0647\u06d5\u0698\u0645\u0627\u0631\u0627 \u062a\u06d5 \u0646\u0648\u06a9\u06d5 \u062f\u0647\u06ce\u062a\u06d5 \u0646\u0627\u0686\u0627\u0644\u0627\u06a9\u06a9\u0631\u0646 \u0648 \u062f \u0646\u0627\u06a4\u0628\u06d5\u0631\u0627 30 \u0631\u06c6\u0698\u0627\u0646\u062f\u0627 \u0628 \u062a\u06d5\u0648\u0627\u0648\u06cc \u062f\u0647\u06ce\u062a\u06d5 \u0698\u06ce\u0628\u0631\u0646. \u0646\u0627\u0647\u06ce\u062a\u06d5 \u0632\u06a4\u0631\u0627\u0646\u062f\u0646. \u067e\u06d5\u06cc\u06a4\u0627 \u0646\u0647\u06ce\u0646\u06cc \u06cc\u0627 \u062e\u06c6 \u0628\u0646\u06a4\u06ce\u0633\u06d5 \u0628\u06c6 \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06a9\u0631\u0646\u06ce."},
gKK(){return"\u067e\u06d5\u06cc\u06a4\u0627 \u0646\u0647\u06ce\u0646\u06cc \u06cc\u0627 \u062e\u06d5\u0644\u06d5\u062a\u06d5."},
gKl(){return"\u0647\u0627\u062a\u06d5 \u0646\u0648\u06cc\u06a9\u0631\u0646."},
gKH(){return"\u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u06ce\u0646 \u06af\u0631\u06ce\u062f\u0627\u06cc"},
gyQ(){return"\u0626\u06d5\u0648 \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u06ce\u0646 \u0626\u06d5\u06a4 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06d5 \u062f\u0634\u06ce\u062a \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u0628\u06c6 \u0628\u0647\u0646\u06ce\u0631\u06cc\u062a. \u06cc\u06d5\u06a9\u06ce \u0632\u06ce\u062f\u06d5 \u0628\u06a9\u06d5 \u062f\u0627 \u062f\u06a9\u062a\u06c6\u0631 \u0628\u0634\u06ce\u062a \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u06ce \u0631\u0627\u0633\u062a\u06d5\u0648\u062e\u06c6 \u0698 \u062a\u0627\u0628\u0627 \u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06cc\u06ce \u06cc\u0627 \u0686\u0627\u0631\u06d5\u0633\u06d5\u0631\u06cc\u06d5\u06a9\u06ce \u0628\u0647\u0646\u06ce\u0631\u06cc\u062a \u0644 \u062c\u0647\u06ce \u0626\u06d5\u067e\u06ce \u067e\u06c6\u0631\u062a\u0627\u0644\u0627 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06ce \u06cc\u06ce \u062c\u0648\u062f\u0627."},
gKm(){return"\u0632\u06ce\u062f\u06d5\u06a9\u0631\u0646\u0627 \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u06ce"},
gKQ(){return"\u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06a9\u0631\u0646\u0627 \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u06ce"},
