gL6(){return"\u0647\u06ce\u0634\u062a\u0627 \u0686 \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647 \u0646\u06d5\u0647\u0627\u062a\u06cc\u0646\u06d5 \u06af\u0631\u06ce\u062f\u0627\u0646."},
gKM(){return"\u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u06ce \u0698\u06ce\u0628\u0628\u06d5\u06cc\u061f"},
KL(a){return'"'+a+'" \u0698 \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u06ce\u0646 \u06af\u0631\u06ce\u062f\u0627\u06cc \u0698\u06ce\u0628\u0628\u06d5\u06cc\u061f \u0626\u06d5\u0648 \u062f\u06a9\u062a\u06c6\u0631\u06ce\u0646 \u0628\u06d5\u0631\u06cc \u0646\u0648\u06a9\u06d5 \u0686\u0648\u0648\u06cc\u0646\u06d5 \u062a\u06ce\u062f\u0627 \u0647\u06d5\u0698\u0645\u0627\u0631\u0627 \u062e\u06c6 \u062f\u067e\u0627\u0631\u06ce\u0632\u0646\u060c \u0628\u06d5\u0644\u06ce \u0626\u06ce\u062f\u06cc \u0646\u06d5\u0634\u06ce\u0646 \u0644 \u06a4\u06ce\u0631\u06ce \u0647\u06d5\u0644\u0628\u0698\u06ce\u0631\u0646.'},
