gUh(){return"\u0626\u06d5\u06a4 \u0698\u0645\u0627\u0631\u06d5 \u0647\u06ce\u0634\u062a\u0627 \u0646\u06d5\u0647\u0627\u062a\u06cc\u06cc\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646: PIN \u06d5\u06a9\u06ce 6 \u0698\u0645\u0627\u0631\u06d5\u06cc\u06cc \u0647\u06d5\u0644\u0628\u0698\u06ce\u0631\u06d5. \u062f\u06ce \u0628\u06cc\u062a\u06d5 PIN \u06cc\u06ce \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06a9\u0631\u0646\u0627 \u062f\u0648\u0648 \u0647\u06d5\u0646\u06af\u0627\u06a4\u06cc \u06cc\u0627 \u0698\u0645\u0627\u0631\u06ce\u060c \u0644\u06d5\u0648\u0627 \u0628\u067e\u0627\u0631\u06ce\u0632\u06d5."},
Um(a,b){return"\u0646\u06d5\u062e\u06c6\u0634\u06ce\u0646 \u06af\u0631\u06ce\u062f\u0627\u06cc\u06cc: "+a+" \xb7 \u0698\u0645\u0627\u0631\u06ce\u0646 \u0648\u0627\u062a\u0633\u0627\u0628\u06ce: "+b},
gUl(){return"\u0626\u06d5\u06a4\u06cc \u0644\u06cc\u0646\u06a9\u06cc \u062f\u06af\u06d5\u0644 \u0646\u06d5\u062e\u06c6\u0634\u06ce\u0646 \u062e\u06c6 \u067e\u0627\u0631\u06a4\u06d5 \u0628\u06a9\u06d5 (\u067e\u06c6\u0633\u062a\u06d5\u0631\u06d5\u06a9 \u0644 \u067e\u06ce\u0634\u0648\u0627\u0632\u06cc\u06ce\u060c \u0626\u06cc\u0646\u0633\u062a\u0627\u06af\u0631\u0627\u0645\u0627 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06ce). \u062f\u06d5\u0645\u06ce \u0646\u0627\u0645\u06d5 \u0628\u06c6 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06ce \u062f\u0641\u0631\u06ce\u06a9\u06d5\u0646\u060c \u0628\u06c6\u062a \u0641\u0627\u06cc\u0644\u0627 \u0648\u0627\u0646 \u0628 \u0698\u0645\u0627\u0631\u0627 \u062a\u06d5\u0644\u06d5\u0641\u06c6\u0646\u06ce \u06cc\u0627 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u06cc \u0644 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06ce \u062f\u0628\u06cc\u0646\u06cc\u062a."},
gUB(){return"\u062f\u0648\u0648\u0645\u0627\u0647\u06cc\u06a9 \u0647\u06d5\u0646\u06af\u0627\u06a4 \u0644 Meta"},
gUA(){return"\u0644 \u0626\u06d5\u067e\u06ce \u062e\u06c6 \u0644 Meta: WhatsApp \u2190 Configuration \u2190 Webhook \u2190 Edit. Callback URL \u0648 Verify token \u06cc\u06ce\u0646 \u062e\u0648\u0627\u0631\u06ce \u062f\u0627\u0646\u06d5\u060c \xabVerify and save\xbb \u062f\u0627\u0628\u06af\u0631\u06d5\u060c \u067e\u0627\u0634\u0627\u0646 \u0644 Webhook fields \u0628\u06d5\u0634\u062f\u0627\u0631\u06cc\u0627 \xabmessages\xbb \u0628\u06a9\u06d5."},
gUa(){return"Callback URL"},
gUx(){return"Verify token"},
gUz(){return"\u06af\u0631\u06ce\u062f\u0627\u06cc\u06d5: \u0646\u0627\u0645\u06ce\u0646 \u0646\u06d5\u062e\u06c6\u0634\u0627\u0646 \u062f\u06af\u06d5\u0647\u0646\u06d5 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06ce."},
gUu(){return"\u0642\u0627\u0644\u0628\u06ce\u0646 \u0646\u0627\u0645\u0627\u0646"},
gUt(){return"Meta \u067e\u06ce\u062f\u0627\u0686\u0648\u0648\u0646\u06ce \u0628 \u0648\u0627\u0646 \u0647\u06d5\u0631\u062f\u0648\u0648 \u0642\u0627\u0644\u0628\u0627\u0646 \u062f\u06a9\u06d5\u062a \u06cc\u06ce\u0646 IQ Clinics \u0686\u06ce\u06a9\u0631\u06cc\u0646 (\u067e\u062a\u0631\u06cc\u0627 \u062c\u0627\u0631\u0627\u0646 \u0686\u06d5\u0646\u062f \u062e\u0648\u0644\u06d5\u06a9\u060c \u0647\u06d5\u062a\u0627 \u0695\u06c6\u0698\u06d5\u06a9\u06ce). \u0628\u06cc\u0631\u0626\u06cc\u0646\u0627\u0646\u060c \u0648 \u0626\u06d5\u0648 \u0646\u0627\u0645\u06ce\u0646 \u0628\u06c6 \u0646\u06d5\u062e\u06c6\u0634\u06d5\u06a9\u06ce \u062f\u0686\u0646 \u06cc\u06ce \u062f 24 \u062f\u06d5\u0645\u0698\u0645\u06ce\u0631\u06ce\u0646 \u0628\u06c6\u0631\u06cc \u062f\u0627 \u0646\u0627\u0645\u06d5 \u0646\u06d5\u0641\u0631\u06ce\u06a9\u0631\u06cc\u060c \u067e\u0634\u062a\u06cc \u067e\u06d5\u0633\u06d5\u0646\u062f\u06a9\u0631\u0646\u06ce \u062f\u06d5\u0633\u062a\u067e\u06ce\u062f\u06a9\u06d5\u0646. \u0626\u0627\u062e\u0641\u062a\u0646 \u062f\u06af\u06d5\u0644 \u0646\u06d5\u062e\u06c6\u0634\u0627\u0646 \u062f\u06d5\u0633\u062a\u0628\u06d5\u062c\u06ce \u06a9\u0627\u0631 \u062f\u06a9\u06d5\u062a."},
gUr(){return"\u0628\u06cc\u0631\u0626\u06cc\u0646\u0627\u0646\u0627 \u0633\u06d5\u0631\u06d5\u062f\u0627\u0646\u06ce"},
